import sys


def pluck(arr):
    if not arr:
        return []

    min_even_value = sys.maxsize
    min_even_index = -1

    for i, value in enumerate(arr):
        if value % 2 == 0:
            if value < min_even_value:
                min_even_value = value
                min_even_index = i

    if min_even_index == -1:
        return []

    return [min_even_value, min_even_index]

