def tri(n):
    """Returns the first n+1 numbers of the Tribonacci sequence."""
    if n == 0:
        return []
    elif n == 1:
        return [3]
    elif n == 2:
        return [3, 2]
    else:
        sequence = [3, 2]
        for i in range(2, n):
            if i % 2 == 0:
                sequence.append(sequence[-1] + sequence[-2] // 2)
            else:
                next_value = sequence[-1] + sequence[-2] + sequence[-3]
                sequence.append(next_value)
        return sequence + [sequence[-1]]

